{
  "steps": [
    {
      "title": "დაარეგულირე სიმაღლე",
      "text": "გამოსწიე ყვითელი ღილაკი სავარძლის ქვეშ და ისე დააყენე, რომ ჯდომისას მუხლები ბალიშების ქვეშ მჭიდროდ მოექცეს.",
      "focus": ["p7", "p6"],
      "avoid": ["p3"],
      "markers": [
        {"part": "p7", "label": "სიმაღლის რეგულირება", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფოტო ბუნდოვანია; სავარძლის ქვეშ მდებარეობისა და აღწერის მიხედვით სარეგულირებელ ღილაკად შერჩეულია p7. სიმაღლე დატვირთვის გარეშე შეცვალე და დაჯდომამდე დარწმუნდი, რომ სავარძელი დაფიქსირდა."
    },
    {
      "title": "აირჩიე წონა",
      "text": "ყვითელი ქინძისთავი გადაიტანე სასურველ ფილაში და ბოლომდე ჩაარჭე.",
      "focus": ["p3", "p2"],
      "avoid": ["p7"],
      "markers": [
        {"part": "p3", "label": "წონის ამომრჩევი", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ფილების გვერდით მდებარე ყვითელი დეტალი სავარაუდოდ p3-ია; ფოტო ბუნდოვანია. წონა შეცვალე მხოლოდ მაშინ, როცა ფილები სრულად დაშვებული და უძრავია; თითები ფილებს შორის არ მოათავსო."
    },
    {
      "title": "მოკიდე სახელურს",
      "text": "ფეხზე მდგომმა მოკიდე ხელი მოხრილ ბოლოებთან, მხრებზე ოდნავ ფართოდ, ხელისგულები წინ.",
      "focus": ["p1"],
      "avoid": [],
      "markers": [
        {"part": "p1", "label": "ზედა განიერი სახელური", "tone": "brand"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "მოჭიდების სიგანე სხეულს მოარგე; ფოტოდან ზუსტი მანძილი ვერ დასტურდება. სახელურს მისაწვდომად სავარძელზე ნუ დადგები."
    },
    {
      "title": "დაჯექი და დაფიქსირდი",
      "text": "სახელურით ხელში დაჯექი, ფეხები იატაკზე, მუხლები ბალიშების ქვეშ. მკერდი წინ, ზურგი სწორი.",
      "focus": ["p6", "p4", "p5", "p1"],
      "avoid": ["p3", "p7"],
      "markers": [
        {"part": "p6", "label": "დაჯექი", "tone": "brand"},
        {"part": "p4", "label": "ბარძაყის დამჭერი", "tone": "neutral"},
        {"part": "p5", "label": "ბარძაყის დამჭერი", "tone": "neutral"}
      ],
      "arrows": [],
      "tools": [],
      "warn": "ორივე ბალიში გამოიყენება დასაფიქსირებლად. ბალიშები ბარძაყებს მუხლებთან ახლოს უნდა ეყრდნობოდეს და არა უშუალოდ მუხლის სახსრებს."
    },
    {
      "title": "ჩამოწიე მკერდამდე",
      "text": "იდაყვები ქვემოთ და უკან, სახელური მკერდის ზედა ნაწილამდე. ზემოთ ნელა აუშვი, 2 წამში.",
      "focus": ["p1"],
      "avoid": ["p2", "p3", "p7"],
      "markers": [
        {"part": "p1", "label": "აკონტროლე მოძრაობა", "tone": "brand"}
      ],
      "arrows": [
        {"part": "p1", "type": "move", "dir": "down"},
        {"part": "p1", "type": "move", "dir": "up"}
      ],
      "tools": [],
      "warn": "სახელური კისრის უკან არ ჩამოწიო და ტანი არ აქანაო. ტკივილის შემთხვევაში შეწყვიტე. 2 წამი ინსტრუქციით მოცემული ტემპია და არა ფოტოდან დადგენილი მონაცემი."
    }
  ],
  "unknown_parts": []
}
